"""Storage backend contract for MemPalace (RFC 001).

This module defines the surface every storage backend must implement:

* ``BaseCollection`` — the per-collection read/write interface, kwargs-only.
* ``BaseBackend`` — the per-palace factory, addressed by ``PalaceRef``.
* ``QueryResult`` / ``GetResult`` — typed result dataclasses that replace the
  Chroma dict shape as the canonical return type.
* Error classes + ``HealthStatus`` — uniform across backends.

This is the v1 cleanup from RFC 001 §10: full typed results, ``PalaceRef``,
registry-ready ABC. Embedder injection, maintenance hooks, and the full
conformance suite land in follow-up PRs.
"""

from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import ClassVar, Optional


# ---------------------------------------------------------------------------
# Errors
# ---------------------------------------------------------------------------


class BackendError(Exception):
    """Base class for every storage-backend error raised by core."""


class PalaceNotFoundError(BackendError, FileNotFoundError):
    """Raised when ``get_collection(create=False)`` is called on a missing palace.

    Subclass of ``FileNotFoundError`` so legacy callers that catch the latter
    (pre-#413 seam) keep working unchanged.
    """


class BackendClosedError(BackendError):
    """Raised when a backend method is called after ``close()``."""


class UnsupportedFilterError(BackendError):
    """Raised when a where-clause uses an operator the backend does not implement.

    Silent dropping of unknown operators is forbidden by spec (RFC 001 §1.4).
    """


class DimensionMismatchError(BackendError):
    """Raised when the embedding dimension on write does not match the collection."""


class EmbedderIdentityMismatchError(BackendError):
    """Raised when the stored embedder model name differs from the current one."""


# ---------------------------------------------------------------------------
# Value objects
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class PalaceRef:
    """A handle to a palace, consumed by backends.

    ``id`` is always present and is the key backends use to cache handles.
    ``local_path`` is populated for filesystem-rooted palaces.
    ``namespace`` is used by server-mode backends for tenant / prefix routing.
    """

    id: str
    local_path: Optional[str] = None
    namespace: Optional[str] = None


@dataclass(frozen=True)
class HealthStatus:
    ok: bool
    detail: str = ""

    @classmethod
    def healthy(cls, detail: str = "") -> "HealthStatus":
        return cls(ok=True, detail=detail)

    @classmethod
    def unhealthy(cls, detail: str) -> "HealthStatus":
        return cls(ok=False, detail=detail)


_TYPED_RESULT_FIELDS = ("ids", "documents", "metadatas", "distances", "embeddings")


class _DictCompatMixin:
    """Transitional dict-protocol access for typed results.

    RFC 001 §1.3 spec is attribute access (``result.ids``). The ``result["ids"]``
    and ``result.get("ids")`` forms are retained as a migration shim for callers
    that predate the typed interface and are scheduled for removal in a follow-
    up cleanup. New code MUST use attribute access.
    """

    def __getitem__(self, key: str):
        if key in _TYPED_RESULT_FIELDS:
            return getattr(self, key)
        raise KeyError(key)

    def get(self, key: str, default=None):
        if key in _TYPED_RESULT_FIELDS:
            val = getattr(self, key, default)
            return default if val is None else val
        return default

    def __contains__(self, key: object) -> bool:
        return key in _TYPED_RESULT_FIELDS and getattr(self, key, None) is not None


@dataclass(frozen=True)
class QueryResult(_DictCompatMixin):
    """Typed return from ``BaseCollection.query``.

    Outer list dimension = number of query vectors / texts.
    Inner list dimension = hits per query (may be zero).

    Fields not in ``include=`` at the call site are populated with empty lists
    of the correct outer shape (never ``None``), except ``embeddings`` which
    is ``None`` when not requested.
    """

    ids: list[list[str]]
    documents: list[list[str]]
    metadatas: list[list[dict]]
    distances: list[list[float]]
    embeddings: Optional[list[list[list[float]]]] = None

    @classmethod
    def empty(cls, num_queries: int = 1, embeddings_requested: bool = False) -> "QueryResult":
        """Construct an all-empty result preserving outer dimension.

        When ``embeddings_requested`` is True, ``embeddings`` preserves the outer
        query dimension with empty hit lists (matching the spec's rule that fields
        requested via ``include=`` carry the outer shape even when empty). When
        False, ``embeddings`` stays ``None`` to signal the field was not requested.
        """
        empty_outer = [[] for _ in range(num_queries)]
        return cls(
            ids=[[] for _ in range(num_queries)],
            documents=[[] for _ in range(num_queries)],
            metadatas=[[] for _ in range(num_queries)],
            distances=[[] for _ in range(num_queries)],
            embeddings=empty_outer if embeddings_requested else None,
        )


@dataclass(frozen=True)
class GetResult(_DictCompatMixin):
    """Typed return from ``BaseCollection.get``."""

    ids: list[str]
    documents: list[str]
    metadatas: list[dict]
    embeddings: Optional[list[list[float]]] = None

    @classmethod
    def empty(cls) -> "GetResult":
        return cls(ids=[], documents=[], metadatas=[], embeddings=None)


# ---------------------------------------------------------------------------
# Collection contract
# ---------------------------------------------------------------------------


class BaseCollection(ABC):
    """Per-collection read/write surface every backend must implement."""

    @abstractmethod
    def add(
        self,
        *,
        documents: list[str],
        ids: list[str],
        metadatas: Optional[list[dict]] = None,
        embeddings: Optional[list[list[float]]] = None,
    ) -> None: ...

    @abstractmethod
    def upsert(
        self,
        *,
        documents: list[str],
        ids: list[str],
        metadatas: Optional[list[dict]] = None,
        embeddings: Optional[list[list[float]]] = None,
    ) -> None: ...

    @abstractmethod
    def query(
        self,
        *,
        query_texts: Optional[list[str]] = None,
        query_embeddings: Optional[list[list[float]]] = None,
        n_results: int = 10,
        where: Optional[dict] = None,
        where_document: Optional[dict] = None,
        include: Optional[list[str]] = None,
    ) -> QueryResult: ...

    @abstractmethod
    def get(
        self,
        *,
        ids: Optional[list[str]] = None,
        where: Optional[dict] = None,
        where_document: Optional[dict] = None,
        limit: Optional[int] = None,
        offset: Optional[int] = None,
        include: Optional[list[str]] = None,
    ) -> GetResult: ...

    @abstractmethod
    def delete(
        self,
        *,
        ids: Optional[list[str]] = None,
        where: Optional[dict] = None,
    ) -> None: ...

    @abstractmethod
    def count(self) -> int: ...

    # ------------------------------------------------------------------
    # Optional methods with ABC defaults (spec §1.2)
    # ------------------------------------------------------------------

    def estimated_count(self) -> int:
        return self.count()

    def close(self) -> None:
        return None

    def health(self) -> HealthStatus:
        return HealthStatus.healthy()

    def update(
        self,
        *,
        ids: list[str],
        documents: Optional[list[str]] = None,
        metadatas: Optional[list[dict]] = None,
        embeddings: Optional[list[list[float]]] = None,
    ) -> None:
        """Default non-atomic update: get + merge + upsert.

        Backends advertising ``supports_update`` MUST override with an atomic
        single-round-trip implementation.
        """
        if documents is None and metadatas is None and embeddings is None:
            raise ValueError("update requires at least one of documents, metadatas, embeddings")

        n = len(ids)
        for label, value in (
            ("documents", documents),
            ("metadatas", metadatas),
            ("embeddings", embeddings),
        ):
            if value is not None and len(value) != n:
                raise ValueError(f"{label} length {len(value)} does not match ids length {n}")

        existing = self.get(ids=ids, include=["documents", "metadatas"])
        by_id = {
            rid: (existing.documents[i], existing.metadatas[i])
            for i, rid in enumerate(existing.ids)
        }
        merged_docs: list[str] = []
        merged_metas: list[dict] = []
        for i, rid in enumerate(ids):
            prev_doc, prev_meta = by_id.get(rid, ("", {}))
            merged_docs.append(documents[i] if documents is not None else prev_doc)
            new_meta = dict(prev_meta or {})
            if metadatas is not None:
                new_meta.update(metadatas[i] or {})
            merged_metas.append(new_meta)
        self.upsert(
            documents=merged_docs,
            ids=list(ids),
            metadatas=merged_metas,
            embeddings=embeddings,
        )


# ---------------------------------------------------------------------------
# Backend contract
# ---------------------------------------------------------------------------


class BaseBackend(ABC):
    """Long-lived factory serving many palaces (RFC 001 §2).

    Instances are lightweight on construction — no I/O, no network. All
    connection work is deferred to ``get_collection``. Instances are thread-
    safe for concurrent ``get_collection`` calls across different palaces.
    """

    name: ClassVar[str]
    spec_version: ClassVar[str] = "1.0"
    capabilities: ClassVar[frozenset[str]] = frozenset()

    @abstractmethod
    def get_collection(
        self,
        *,
        palace: PalaceRef,
        collection_name: str,
        create: bool = False,
        options: Optional[dict] = None,
    ) -> BaseCollection: ...

    def close_palace(self, palace: PalaceRef) -> None:
        """Evict cached handles for a single palace. Default: no-op."""
        return None

    def close(self) -> None:
        """Shut down the entire backend. Default: no-op."""
        return None

    def health(self, palace: Optional[PalaceRef] = None) -> HealthStatus:
        return HealthStatus.healthy()

    # Optional detection hint used by selection priority (RFC 001 §3.3 (4)):
    @classmethod
    def detect(cls, path: str) -> bool:  # pragma: no cover - default hook
        return False


# ---------------------------------------------------------------------------
# Adapter utilities
# ---------------------------------------------------------------------------


# Keys the Chroma ``include=`` parameter accepts.
_VALID_INCLUDE_KEYS = frozenset({"documents", "metadatas", "distances", "embeddings"})


@dataclass
class _IncludeSpec:
    """Resolve an ``include=`` parameter with spec-mandated defaults."""

    documents: bool = True
    metadatas: bool = True
    distances: bool = True  # only meaningful for query
    embeddings: bool = False

    @classmethod
    def resolve(
        cls, include: Optional[list[str]], *, default_distances: bool = True
    ) -> "_IncludeSpec":
        if include is None:
            return cls(
                documents=True,
                metadatas=True,
                distances=default_distances,
                embeddings=False,
            )
        keys = {k for k in include if k in _VALID_INCLUDE_KEYS}
        return cls(
            documents="documents" in keys,
            metadatas="metadatas" in keys,
            distances="distances" in keys,
            embeddings="embeddings" in keys,
        )

"""Hybrid search: BM25 + semantic embeddings (ADR-001)."""

from __future__ import annotations

import logging

from palaia.bm25 import BM25, tokenize  # noqa: F401 — re-exported for backward compat
from palaia.embeddings import (
    BM25Provider,
    _create_provider,
    _resolve_embedding_models,
    auto_detect_provider,
    cosine_similarity,
    detect_providers,
    get_provider_display_info,
)

logger = logging.getLogger(__name__)


def detect_search_tier() -> int:
    """Detect best available search tier.

    Returns:
        1: BM25 only
        2: Local embeddings (ollama, sentence-transformers, fastembed)
        3: API embeddings (OpenAI)
    """
    from palaia.embeddings import detect_providers

    providers = detect_providers()
    for p in providers:
        if p["available"]:
            if p["name"] == "openai":
                return 3
            elif p["name"] in ("ollama", "sentence-transformers", "fastembed"):
                return 2
    return 1


def _resolve_semantic_provider(config: dict):
    """Resolve the semantic embedding provider respecting embedding_chain config.

    Reads ``embedding_chain`` from *config*, iterates over its entries (skipping
    ``"bm25"``), and returns the first provider that can be instantiated.
    Falls back to ``auto_detect_provider()`` when the chain is absent, empty,
    contains only ``"bm25"``, or none of its semantic entries are available.
    """
    chain = config.get("embedding_chain")
    if chain and isinstance(chain, list):
        models = _resolve_embedding_models(config)
        available = {p["name"] for p in detect_providers() if p["available"]}
        for name in chain:
            if name == "bm25":
                continue
            if name not in available:
                continue
            try:
                return _create_provider(name, models.get(name))
            except (ImportError, ValueError):
                continue
    # No chain configured or no chain provider available → legacy fallback
    return auto_detect_provider(config)


class SearchEngine:
    """Unified hybrid search: BM25 + semantic embeddings."""

    def __init__(self, store, config: dict | None = None):
        self.store = store
        self.bm25 = BM25()
        self.config = config or store.config
        self._provider = None
        self._index_cache: list[tuple[str, str, dict]] | None = None
        self._index_dirty = True
        self._index_cache_key: tuple | None = None  # (include_cold, agent) for cache validity

    @property
    def provider(self):
        if self._provider is None:
            self._provider = _resolve_semantic_provider(self.config)
        return self._provider

    @property
    def has_embeddings(self) -> bool:
        return not isinstance(self.provider, BM25Provider)

    def invalidate_index(self) -> None:
        """Mark the cached BM25 index as dirty. Call after store modifications."""
        self._index_dirty = True
        self._index_cache = None

    def build_index(
        self, include_cold: bool = False, agent: str | None = None,
        scope_visibility: list[str] | None = None,
    ) -> list[tuple[str, str, dict]]:
        """Build search index from store entries. Returns (doc_id, full_text, meta) list.

        Uses a cached index when available. Call invalidate_index() after
        write/edit/gc operations to force a rebuild.
        """
        cache_key = (include_cold, agent, tuple(scope_visibility) if scope_visibility else None)
        if not self._index_dirty and self._index_cache is not None and self._index_cache_key == cache_key:
            # Re-index BM25 from cache (cheap — no disk reads)
            self.bm25.index([(did, text) for did, text, _meta in self._index_cache])
            return list(self._index_cache)

        entries = self.store.all_entries(include_cold=include_cold, agent=agent, scope_visibility=scope_visibility)
        docs = []
        docs_with_meta = []
        for meta, body, tier in entries:
            doc_id = meta.get("id", "unknown")
            title = meta.get("title", "")
            tags = " ".join(meta.get("tags", []))
            full_text = f"{title} {tags} {body}"
            docs.append((doc_id, full_text))
            docs_with_meta.append((doc_id, full_text, meta))
        self.bm25.index(docs)
        self._index_cache = docs_with_meta
        self._index_cache_key = cache_key
        self._index_dirty = False
        return docs_with_meta

    def search(
        self,
        query: str,
        top_k: int = 10,
        include_cold: bool = False,
        project: str | None = None,
        agent: str | None = None,
        entry_type: str | None = None,
        status: str | None = None,
        priority: str | None = None,
        assignee: str | None = None,
        instance: str | None = None,
        before: str | None = None,
        after: str | None = None,
        cross_project: bool = False,
        scope_visibility: list[str] | None = None,
    ) -> list[dict]:
        """Search memories using hybrid ranking (BM25 + embeddings when available).

        Structured filters (type, status, priority, assignee, instance) use exact match,
        not embeddings.

        Temporal filters (before, after) filter by entry created timestamp.
        cross_project=True ignores project filter and searches across all projects.
        scope_visibility: If set, only entries with matching scope are included (Issue #145).
        """
        docs_with_meta = self.build_index(include_cold=include_cold, agent=agent, scope_visibility=scope_visibility)

        # Apply structured filters (exact match, pre-BM25)
        if project and not cross_project:
            docs_with_meta = [(did, text, meta) for did, text, meta in docs_with_meta if meta.get("project") == project]
        if entry_type:
            docs_with_meta = [
                (did, text, meta) for did, text, meta in docs_with_meta if meta.get("type", "memory") == entry_type
            ]
        if status:
            docs_with_meta = [(did, text, meta) for did, text, meta in docs_with_meta if meta.get("status") == status]
        if priority:
            docs_with_meta = [
                (did, text, meta) for did, text, meta in docs_with_meta if meta.get("priority") == priority
            ]
        if assignee:
            docs_with_meta = [
                (did, text, meta) for did, text, meta in docs_with_meta if meta.get("assignee") == assignee
            ]
        if instance:
            docs_with_meta = [
                (did, text, meta) for did, text, meta in docs_with_meta if meta.get("instance") == instance
            ]

        # Temporal filters (Issue #74)
        if before:
            docs_with_meta = [
                (did, text, meta) for did, text, meta in docs_with_meta if meta.get("created", "") < before
            ]
        if after:
            docs_with_meta = [
                (did, text, meta) for did, text, meta in docs_with_meta if meta.get("created", "") > after
            ]

        if project or entry_type or status or priority or assignee or instance or before or after:
            # Rebuild BM25 index with filtered docs
            self.bm25.index([(did, text) for did, text, meta in docs_with_meta])

        # BM25 scores
        bm25_results = self.bm25.search(query, top_k=top_k * 2)  # get more candidates for hybrid
        bm25_scores = {doc_id: score for doc_id, score in bm25_results}

        # Normalize BM25 scores to [0, 1]
        max_bm25 = max(bm25_scores.values()) if bm25_scores else 1.0
        bm25_norm = {k: v / max_bm25 for k, v in bm25_scores.items()} if max_bm25 > 0 else {}

        # Embedding scores (if available)
        embed_norm = {}
        if self.has_embeddings and docs_with_meta:
            try:
                query_vec = self.provider.embed_query(query)

                # Fast path: use backend-native vector search (sqlite-vec / pgvector)
                backend = getattr(self.store, "_backend", None)
                is_postgres = backend is not None and type(backend).__name__ == "PostgresBackend"
                has_native_vec = (
                    backend is not None
                    and hasattr(backend, "vector_search")
                    and (getattr(backend, "_has_vec", False) or is_postgres)
                )

                if has_native_vec:
                    # Embed any uncached BM25 candidates first so they're in the DB
                    candidate_ids = set(bm25_scores.keys())
                    texts_to_embed = []
                    ids_to_embed = []
                    for doc_id, full_text, meta in docs_with_meta:
                        cached = self.store.embedding_cache.get_cached(doc_id)
                        if cached is None and (doc_id in candidate_ids or len(texts_to_embed) < top_k):
                            texts_to_embed.append(full_text)
                            ids_to_embed.append(doc_id)

                    if texts_to_embed:
                        vectors = self.provider.embed(texts_to_embed)
                        model_name = getattr(self.provider, "model_name", None) or getattr(
                            self.provider, "model", "unknown"
                        )
                        for doc_id, vec in zip(ids_to_embed, vectors):
                            self.store.embedding_cache.set_cached(doc_id, vec, model=model_name)

                    # Native KNN search (SIMD-accelerated)
                    vec_results = backend.vector_search(query_vec, top_k=top_k * 2)
                    embed_norm = {doc_id: sim for doc_id, sim in vec_results}
                else:
                    # Fallback: Python cosine similarity (no native vector search)
                    candidate_ids = set(bm25_scores.keys())
                    texts_to_embed = []
                    ids_to_embed = []
                    for doc_id, full_text, meta in docs_with_meta:
                        cached = self.store.embedding_cache.get_cached(doc_id)
                        if cached:
                            sim = cosine_similarity(query_vec, cached)
                            embed_norm[doc_id] = sim
                        elif doc_id in candidate_ids or len(texts_to_embed) < top_k:
                            texts_to_embed.append(full_text)
                            ids_to_embed.append(doc_id)

                    if texts_to_embed:
                        vectors = self.provider.embed(texts_to_embed)
                        model_name = getattr(self.provider, "model_name", None) or getattr(
                            self.provider, "model", "unknown"
                        )
                        for doc_id, vec in zip(ids_to_embed, vectors):
                            self.store.embedding_cache.set_cached(doc_id, vec, model=model_name)
                            sim = cosine_similarity(query_vec, vec)
                            embed_norm[doc_id] = sim
            except Exception as e:
                # If embedding fails, fall back to BM25 only
                logger.warning("Embedding search failed, using BM25 only: %s", e)
                embed_norm = {}

        # Combine scores: hybrid ranking
        all_ids = set(bm25_norm.keys()) | set(embed_norm.keys())
        combined = {}
        for doc_id in all_ids:
            bm25_s = bm25_norm.get(doc_id, 0.0)
            embed_s = embed_norm.get(doc_id, 0.0)
            if embed_norm:
                # Weighted combination: 40% BM25 + 60% embedding
                combined[doc_id] = 0.4 * bm25_s + 0.6 * embed_s
            else:
                combined[doc_id] = bm25_s

        # Sort by combined score
        ranked = sorted(combined.items(), key=lambda x: x[1], reverse=True)[:top_k]

        # Build output
        output = []
        for doc_id, score in ranked:
            entry = self.store.read(doc_id)
            if entry:
                meta, body = entry
                result_entry = {
                    "id": doc_id,
                    "score": round(score, 4),
                    "bm25_score": round(bm25_norm.get(doc_id, 0.0), 4),
                    "embed_score": round(embed_norm.get(doc_id, 0.0), 4),
                    "type": meta.get("type", "memory"),
                    "scope": meta.get("scope", "team"),
                    "title": meta.get("title", ""),
                    "tags": meta.get("tags", []),
                    "body": body[:200] + ("..." if len(body) > 200 else ""),
                    "tier": self._get_tier(doc_id),
                    "decay_score": meta.get("decay_score", 0),
                }
                # Include task fields if present
                if meta.get("status"):
                    result_entry["status"] = meta["status"]
                if meta.get("priority"):
                    result_entry["priority"] = meta["priority"]
                if meta.get("assignee"):
                    result_entry["assignee"] = meta["assignee"]
                if meta.get("due_date"):
                    result_entry["due_date"] = meta["due_date"]
                if meta.get("instance"):
                    result_entry["instance"] = meta["instance"]
                if meta.get("project"):
                    result_entry["project"] = meta["project"]
                output.append(result_entry)
        return output

    def _get_tier(self, entry_id: str) -> str:
        """Determine which tier an entry is in."""
        for tier in ("hot", "warm", "cold"):
            if (self.store.root / tier / f"{entry_id}.md").exists():
                return tier
        return "unknown"

    def search_info(self) -> dict:
        """Get info about current search configuration."""
        provider = self.provider
        provider_display = get_provider_display_info(provider)
        has_embed = self.has_embeddings
        return {
            "provider": provider_display,
            "has_embeddings": has_embed,
            "bm25_active": True,
            "semantic_active": has_embed,
        }
